using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace MeridianStudio.Implementation.RealTimeDataIngestionAnalysisPipelines
{
    public sealed record TransactionData(string TransactionId, decimal Amount, string Currency, DateTime Timestamp, string SenderId, string ReceiverId, string Description);
    public sealed record AnalysisResult(string TransactionId, bool IsSuspicious, decimal ConfidenceScore, string Reason);
    public sealed record PipelineOptions
    {
        public string IngestionEndpoint { get; init; } = "";
        public int BatchSize { get; init; } = 100;
        public TimeSpan ProcessingInterval { get; init; } = TimeSpan.FromSeconds(5);
    }

    public interface IDataIngestionService
    {
        Task<IEnumerable<TransactionData>> IngestTransactionsAsync(CancellationToken cancellationToken = default);
    }

    public interface ITransactionAnalysisService
    {
        Task<AnalysisResult> AnalyzeTransactionAsync(TransactionData transaction, CancellationToken cancellationToken = default);
    }

    public class RealTimePipelineService
    {
        private readonly ILogger<RealTimePipelineService> _logger;
        private readonly IOptions<PipelineOptions> _options;
        private readonly IDataIngestionService _ingestionService;
        private readonly ITransactionAnalysisService _analysisService;

        public RealTimePipelineService(ILogger<RealTimePipelineService> logger, IOptions<PipelineOptions> options, IDataIngestionService ingestionService, ITransactionAnalysisService analysisService)
        {
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
            _options = options ?? throw new ArgumentNullException(nameof(options));
            _ingestionService = ingestionService ?? throw new ArgumentNullException(nameof(ingestionService));
            _analysisService = analysisService ?? throw new ArgumentNullException(nameof(analysisService));
        }

        public async Task RunPipelineAsync(CancellationToken cancellationToken = default)
        {
            _logger.LogInformation("Starting real-time data ingestion and analysis pipeline.");
            try
            {
                while (!cancellationToken.IsCancellationRequested)
                {
                    _logger.LogInformation("Attempting to ingest transactions...");
                    var transactions = await _ingestionService.IngestTransactionsAsync(cancellationToken);
                    _logger.LogInformation("Ingested {Count} transactions.", transactions.Count());

                    var analysisTasks = new List<Task<AnalysisResult>>();
                    foreach (var transaction in transactions)
                    {
                        analysisTasks.Add(_analysisService.AnalyzeTransactionAsync(transaction, cancellationToken));
                    }

                    var results = await Task.WhenAll(analysisTasks);
                    ProcessAnalysisResults(results);

                    await Task.Delay(_options.Value.ProcessingInterval, cancellationToken);
                }
            }
            catch (OperationCanceledException)
            {
                _logger.LogInformation("Pipeline operation cancelled.");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "An error occurred during pipeline execution.");
                throw;
            }
            finally
            {
                _logger.LogInformation("Real-time data ingestion and analysis pipeline stopped.");
            }
        }

        private void ProcessAnalysisResults(IEnumerable<AnalysisResult> results)
        {
            foreach (var result in results)
            {
                if (result.IsSuspicious)
                {
                    _logger.LogWarning("Suspicious transaction detected: {TransactionId} - Reason: {Reason} (Confidence: {ConfidenceScore:P2})", result.TransactionId, result.Reason, result.ConfidenceScore);
                }
                else
                {
                    _logger.LogInformation("Transaction {TransactionId} processed normally.", result.TransactionId);
                }
            }
        }
    }

