    public class MockDataIngestionService : IDataIngestionService
    {
        private readonly ILogger<MockDataIngestionService> _logger;
        public MockDataIngestionService(ILogger<MockDataIngestionService> logger) { _logger = logger; }
        public Task<IEnumerable<TransactionData>> IngestTransactionsAsync(CancellationToken cancellationToken = default)
        {
            _logger.LogDebug("Mock ingestion: returning dummy data.");
            var transactions = new List<TransactionData>
            {
                new TransactionData("TXN123", 1000.50m, "USD", DateTime.UtcNow.AddSeconds(-10), "SENDER001", "RECEIVER002", "Standard payment"),
                new TransactionData("TXN456", 50000.00m, "EUR", DateTime.UtcNow.AddSeconds(-5), "SENDER003", "RECEIVER004", "High value transfer")
            };
            return Task.FromResult(transactions);
        }
    }

    public class MockTransactionAnalysisService : ITransactionAnalysisService
    {
        private readonly ILogger<MockTransactionAnalysisService> _logger;
        public MockTransactionAnalysisService(ILogger<MockTransactionAnalysisService> logger) { _logger = logger; }
        public Task<AnalysisResult> AnalyzeTransactionAsync(TransactionData transaction, CancellationToken cancellationToken = default)
        {
            _logger.LogDebug("Mock analysis for TransactionId: {TransactionId}", transaction.TransactionId);
            bool isSuspicious = transaction.Amount > 40000m || transaction.Description.Contains("suspicious", StringComparison.OrdinalIgnoreCase);
            decimal confidence = isSuspicious ? 0.85m : 0.10m;
            string reason = isSuspicious ? "High value or flagged description" : "Standard processing";
            return Task.FromResult(new AnalysisResult(transaction.TransactionId, isSuspicious, confidence, reason));
        }
    }

    public static class ServiceCollectionExtensions
    {
        public static IServiceCollection AddRealTimePipeline(this IServiceCollection services, Action<PipelineOptions> configureOptions)
        {
            services.Configure(configureOptions);
            services.AddSingleton<IDataIngestionService, MockDataIngestionService>();
            services.AddSingleton<ITransactionAnalysisService, MockTransactionAnalysisService>();
            services.AddHostedService<RealTimePipelineService>();
            return services;
        }
    }
